rss.channel:
{{ site.title | xml_escape }}
{{ site.rss-description | xml_escape }}
{{ '/' | absolute_url }}
{{ site.language }}

{{ site.time | date_to_rfc822 }}
{% for post in site.posts limit:20 %}


    {{ post.title | strip_html | xml_escape }}
    {{ post.author | default: site.author }}
    {% if post.subtitle %}{{ post.subtitle | strip_html | xml_escape }} - {% endif %}{{ post.content | strip_html | xml_escape | truncatewords: site.excerpt_length }}
    {{ post.content | replace: '', ']]>' }}]]>
    {{ post.date | date_to_rfc822 }}
    {{ post.url | absolute_url }}
    {{ post.url | absolute_url }}
    {% for tag in post.tags %}{{ tag | xml_escape }}{% endfor %}

{% endfor %}
